assert len(G) == 27
for a, c, v, r in G:
    p = subprocess.run([sys.executable, "system/controller.py", "gate", "record", "--study", "study-001", "--artifact", a,
                        "--criterion", c, "--verdict", v, "--evaluator", "R5", "--reason", r], capture_output=True, text=True)
